vector<double> rollingZ(vector<double>& p, int w) {
    vector<double> out;
    for (size_t i = w - 1; i < p.size(); i++) { double m = 0; for (size_t j = i + 1 - w; j <= i; j++) m += p[j]; m /= w;
        double v = 0; for (size_t j = i + 1 - w; j <= i; j++) v += (p[j] - m) * (p[j] - m); v /= w;
        out.push_back(v <= 1e-18 ? 0.0 : (p[i] - m) / sqrt(v)); }
    return out;
}
